import os
import requests

SUPERCON_URL = "https://supercon.nims.go.jp/api/search"
MATERIALS_PROJECT_URL = "https://api.materialsproject.org/materials"
MP_API_KEY = os.environ.get("MATERIALS_PROJECT_API_KEY", "")

def fetch_supercon():
    try:
        resp = requests.get(SUPERCON_URL, params={"q": "superconductor", "format": "json"}, timeout=10)
        resp.raise_for_status()
        return resp.json()
    except Exception as e:
        print(f"SuperCon query failed: {e}")
        return []

def fetch_materials_project():
    if not MP_API_KEY:
        print("Materials Project API key not set. Skipping.")
        return []
    headers = {"X-API-KEY": MP_API_KEY}
    try:
        resp = requests.get(MATERIALS_PROJECT_URL, headers=headers, params={"criteria": "superconductor", "fields": "material_id,formula,properties.tc"}, timeout=10)
        resp.raise_for_status()
        return resp.json().get("data", [])
    except Exception as e:
        print(f"Materials Project query failed: {e}")
        return []

def main():
    supercon_data = fetch_supercon()
    mp_data = fetch_materials_project()
    combined = {
        "supercon_data": supercon_data,
        "materials_project_data": mp_data,
        "source": "online query"
    }
    bb_path = "blackboard-state.json"
    if os.path.exists(bb_path):
        with open(bb_path, "r") as f:
            bb = json.load(f)
    else:
        bb = {}
    bb["superconductor_data"] = combined
    with open(bb_path, "w") as f:
        json.dump(bb, f, indent=2)
    print("Data ingestion complete.")

if __name__ == "__main__":
    main()
