import os

def generate_candidates():
    # Known high-Tc families and their doped variants
    candidates = [
        {"formula": "YBa2Cu3O7", "family": "cuprate", "doping": "none", "estimated_tc_range_K": [90, 95]},
        {"formula": "Y0.9Ca0.1Ba2Cu3O7", "family": "cuprate", "doping": "Ca substitution on Y site", "estimated_tc_range_K": [85, 92]},
        {"formula": "YBa1.9Sr0.1Cu3O7", "family": "cuprate", "doping": "Sr substitution on Ba site", "estimated_tc_range_K": [88, 93]},
        {"formula": "Bi2Sr2CaCu2O8.2", "family": "bismuth cuprate", "doping": "oxygen excess", "estimated_tc_range_K": [85, 95]},
        {"formula": "Bi2Sr2Ca0.8Y0.2Cu2O8", "family": "bismuth cuprate", "doping": "Y substitution on Ca site", "estimated_tc_range_K": [80, 90]},
        {"formula": "LaFeAsO0.9F0.1", "family": "iron pnictide", "doping": "F substitution on O site", "estimated_tc_range_K": [26, 30]}
    ]
    return candidates

def update_blackboard(candidates):
    state_path = "blackboard-state.json"
    if not os.path.exists(state_path):
        print(f"Error: {state_path} not found.")
        return
    with open(state_path, "r") as f:
        state = json.load(f)
    state["candidates"] = candidates
    with open(state_path, "w") as f:
        json.dump(state, f, indent=2)
    print(f"Updated {state_path} with {len(candidates)} candidates.")

if __name__ == "__main__":
    cands = generate_candidates()
    update_blackboard(cands)
